    /**
     * Tests getting all FraudSignals.
     *
     * @return    Collection
     */
    public List<FraudSignal> testGetAll() throws Throwable {
    LOGGER.info( "FraudSignalTest:testGetAll() - Retrieving Collection of FraudSignals:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all FraudSignal : " );
    List<FraudSignal> collection  = null;

    try {
        // call the static get method on the FraudSignalService
        collection = service.getAllFraudSignal();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            FraudSignal currEntity  = null;
            Iterator<FraudSignal> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getFraudSignalId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

